"""Write data/cases/MANIFEST.md from the case files' own metadata.

    poetry run python scripts/build_case_manifest.py
"""
from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "src"))

from lex_drl.cases import CASES_DIR, TIERS, case_census, load_all_cases  # noqa: E402

OUT = CASES_DIR / "MANIFEST.md"


def main() -> None:
    cases = load_all_cases()
    census = case_census()
    L = ["# Case manifest", "",
         "Generated by `scripts/build_case_manifest.py` — do not edit by hand.", "",
         f"**{len(cases)} cases.** Patches are mined from `training` cases only and "
         "evaluated on `test` cases.", "",
         "| Tier | training | test | total |", "|---|--:|--:|--:|"]
    for tier in TIERS:
        tr, te = census[tier].get("training", 0), census[tier].get("test", 0)
        L.append(f"| {tier} | {tr} | {te} | {tr + te} |")
    L += ["", "| ID | Tier | Role | Jurisdiction | Doctrinal area | Words |",
          "|---|---|---|---|---|--:|"]
    for c in cases:
        path = next(CASES_DIR.glob(f"{c.case_id}_*.md"))
        words = len(path.read_text(encoding="utf-8").split())
        L.append(f"| {c.case_id} | {c.tier} | {c.role} | {', '.join(c.jurisdiction_tags)} "
                 f"| {c.doctrinal_area} | {words} |")
    L += ["", "E1, E2, M1, M2, H1 and H2 are the original six cases. The other 24 were "
          "written for the Phase 5 learning-curve experiment; they are synthetic fact "
          "patterns and have not yet been reviewed by a legal expert.", ""]
    OUT.write_text("\n".join(L), encoding="utf-8")
    print(f"wrote {OUT} ({len(cases)} cases)")


if __name__ == "__main__":
    main()
